        front: "Virtual File System (VFS) Abstraction",
        back: "A kernel abstraction layer providing a uniform, object-oriented API interface for standard file operations (`read`, `write`, `open`). Allows user applications to access ext4, NTFS, FAT32, NFS, and virtual filesystems seamlessly.",
        coolFact: "In Unix, everything is accessed as a file via VFS—including physical storage drives (`/dev/sda`), network sockets, and kernel parameters (`/proc`)."
