        id: 25,
        front: "Real-Time Operating Systems (RTOS) Determinism",
        back: "Designed to guarantee response times within strict, predictable temporal deadlines (Determinism) rather than maximizing overall system throughput. Hard Real-Time systems consider missing a time deadline a catastrophic total system failure.",
