        back: "Asynchronous notification mechanism sent by the kernel or user processes to signal asynchronous events:\n`SIGINT` (Ctrl+C: Interrupt request).\n`SIGTERM` (Termination request; can be handled/ignored).\n`SIGKILL` (Forceful termination; cannot be caught or ignored).\n`SIGSEGV` (Invalid memory segmentation fault).",
        coolFact: "Because `SIGKILL` (Signal 9) bypasses process execution loops entirely, the kernel instantly destroys the process context without allowing cleanup."
